-- REELS VIRALES · 21-oct-2026 · pegar en Supabase → SQL Editor (proyecto de producción).
-- Añade 18 reels (13 inspiraciones + 5 transiciones). Las portadas viven en la app (/reels/…),
-- así que publica primero la app en Vercel. No duplica: salta los reels cuyo enlace ya exista.

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Soy estilista… pero también soy', 'Un clip trabajando y un texto con giro: todo lo que eres además de estilista', 'Plano fijo de la estilista trabajando y un texto en dos tiempos: «Soy estilista… pero también soy…». El remate (confidente, psicóloga, la que escucha) es lo que se comparte.', 'Grábate trabajando con una clienta, sin hablar, y pon el texto «Soy estilista…» y después el giro: «…pero también soy su psicóloga, su confidente y la que escucha».', 'Humor de identidad: cualquier estilista se ve reflejada y lo comparte con su gremio, y la clienta sonríe porque lo ha vivido en tu silla. Un solo clip y dos textos: cero edición.', 'Un plano fijo de 6–8 s mientras trabajas. Texto en dos tiempos (frase y remate) y un audio en tendencia. Caption: «¿Y tú qué más eres en tu salón?».', '/reels/cover-nov-DeSS5zeJRmT.jpg', 'https://www.instagram.com/reel/DeSS5zeJRmT/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DeSS5zeJRmT%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select '«Tengo una cancelación, ¡ven ya!»', 'Humor de recepción: la llamada que toda clienta quiere recibir', 'Clip en recepción hablando por teléfono con el texto «Tengo una cancelación, ¡ven ahora mismo!». El caption remata: «cuando mi clienta me dice que viene de camino».', 'Clip en tu recepción al teléfono con el texto «Tengo una cancelación, ¡ven ahora mismo!» y una reacción exagerada. En el caption, el remate de la clienta que ya viene corriendo.', 'Una situación cotidiana del salón contada con humor: se entiende en un segundo, se comenta y se envía a la amiga. De paso recuerda que tu agenda está llena.', 'Móvil fijo en la recepción, tú o alguien del equipo al teléfono con gesto exagerado. Texto grande en el centro. 5–7 s para que se repita en bucle.', '/reels/cover-nov-Ded-x9HtU5h.jpg', 'https://www.instagram.com/reel/Ded-x9HtU5h/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%Ded-x9HtU5h%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'La pregunta que hace sonreír a la clienta', 'Charla en el sofá del salón con preguntas personales en pantalla', 'Dos personas en el sofá del estudio; las preguntas cercanas («¿Él te hace reír?») aparecen como subtítulo. El mensaje: aquí siempre hay tiempo para ti.', 'Mientras la clienta espera o se le pone el color, hazle tres o cuatro preguntas cortas y cercanas con el subtítulo en pantalla. Cierra con tu frase: «aquí siempre hay tiempo para ti».', 'Muestra el trato y el ambiente, que es lo que de verdad hace volver. Las preguntas personales enganchan porque todas queremos oír la respuesta.', 'Plano fijo de las dos en el sofá o el tocador con luz cálida. Subtítulos grandes. Pide permiso a la clienta antes de grabar y publica solo lo que ella apruebe.', '/reels/cover-nov-Ddbp7iwgQJW.jpg', 'https://www.instagram.com/reel/Ddbp7iwgQJW/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%Ddbp7iwgQJW%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Señales de un buen día de pelo', 'Clip del resultado rubio con texto tipo lista', 'Un solo clip del resultado con el texto «Señales de un muy buen día de pelo». Sin hablar: el rubio y el movimiento hacen todo el trabajo.', 'Un clip del resultado (la melena moviéndose) con el texto «Señales de que hoy es un buen día de pelo» y dos o tres señales que van apareciendo.', 'Las listas cortas se ven hasta el final y se guardan. El resultado bonito engancha y la lista da la excusa para quedarse.', 'Graba el resultado junto a una ventana, con la clienta moviendo el pelo. Tres textos que aparecen uno tras otro, unos 2 s cada uno, y un audio suave en tendencia.', '/reels/cover-nov-Dd9m0oJB0yX.jpg', 'https://www.instagram.com/reel/Dd9m0oJB0yX/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%Dd9m0oJB0yX%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Bienvenida a mi salón', 'Recorrido por el salón con texto de bienvenida y llamada a reservar', 'Recorrido lento por el salón con el texto «Bienvenida a mi lugar favorito del mundo». El caption cuenta por qué cada clienta es única y termina con «reserva tu cita en el enlace de la bio».', 'Un recorrido lento por tu salón (entrada, tocadores, detalles) con el texto «Bienvenida a mi lugar favorito del mundo». En el caption, por qué cada clienta es única en tu salón.', 'Las clientas nuevas quieren ver dónde se van a sentar. Enseñar el espacio genera confianza y resuelve la duda antes de reservar.', 'Un solo plano caminando despacio (modo estabilizado), con el salón recogido y luz natural. Texto de bienvenida arriba. CTA en el caption: «Reserva tu cita en el enlace de la bio».', '/reels/cover-nov-DdRvUSoTqfR.jpg', 'https://www.instagram.com/reel/DdRvUSoTqfR/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DdRvUSoTqfR%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Tu señal para volver a cuidarte', 'Clip de ambiente relajante con texto y promoción para nuevas clientas', 'Clip tranquilo de la cabina (velas, detalles) con el texto «Tu señal para volver a cuidarte» y, en el caption, una promoción con fecha límite para nuevas citas.', 'Un clip tranquilo de tu salón (velas, lavacabezas, detalles) con el texto «Tu señal para volver a cuidarte» y en el caption una promoción concreta para nuevas citas, con fecha límite.', 'El formato «tu señal para…» habla directamente a quien lo ve. La promoción con fecha límite convierte esa emoción en reservas.', 'Plano de detalle de 6–8 s con luz suave y sin personas. Texto centrado. En el caption: servicio, descuento y fecha (por ejemplo «−15 % en nuevas citas hasta el 30/09»).', '/reels/cover-nov-DdE3-OroCcI.jpg', 'https://www.instagram.com/reel/DdE3-OroCcI/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DdE3-OroCcI%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'El secreto para camuflar tus canas', 'El estilista explica a cámara cómo integrar la raíz de canas', 'El estilista, junto a la clienta, explica por qué se nota «el corte» de las canas y cómo integrarlas de forma natural. 169 comentarios preguntando.', 'Explica en 30 s por qué se nota la línea de las canas a las pocas semanas y qué técnica usas para que se integren de forma natural, señalando la raíz en la clienta.', 'Resuelve un dolor que tienen miles de clientas: la raíz blanca que se nota enseguida. Los comentarios preguntando son clientas potenciales.', 'Tú a cámara junto a la clienta, señalando la raíz. Gancho en pantalla: «El secreto para camuflar tus canas». Explica qué haces y por qué, y cierra con «escríbeme y vemos tu caso».', '/reels/cover-nov-DbV0W7-k7Cg.jpg', 'https://www.instagram.com/reel/DbV0W7-k7Cg/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DbV0W7-k7Cg%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Cortes según tu tipo de rostro', 'A cámara: qué corte favorece a cada rostro', 'El estilista explica a cámara qué corte favorece a cada tipo de rostro. El caption pide guardarlo para la próxima cita y recuerda la promoción de cortes del salón.', 'Explica a cámara qué corte favorece a cada tipo de rostro mientras aparecen fotos de ejemplo detrás de ti.', 'Es la pregunta que toda clienta se hace antes de cortarse. «Guarda este reel para tu próxima cita» lo convierte en contenido de guardado.', 'Fondo liso y tú a cámara con micro. Usa el efecto de pantalla verde de Instagram para poner una foto por rostro. Caption con «guárdalo» y tu promoción de cortes.', '/reels/cover-nov-DdkXattRH-s.jpg', 'https://www.instagram.com/p/DdkXattRH-s/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DdkXattRH-s%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select '¿Shaggy, mullet o sullet?', 'Tres cortes de tendencia explicados con la clienta en el sillón', 'Con la clienta ya peinada, se explica en qué se diferencian tres cortes de tendencia y que no hace falta tener mucho pelo para llevarlos.', 'Con la clienta ya peinada, explica las diferencias entre tres cortes de tendencia y para qué tipo de pelo funciona cada uno.', 'Nombrar tendencias que la gente busca (shaggy, mullet) atrae visitas, y desmontar «necesitas mucho pelo» rompe una objeción frecuente.', 'Plano medio de la clienta con el resultado mientras hablas a su lado, con subtítulos. Cierra con: «la clave está en cómo se adapta el corte a ti».', '/reels/cover-nov-DcwQce6MBj9.jpg', 'https://www.instagram.com/p/DcwQce6MBj9/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DcwQce6MBj9%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Qué corte te queda según tu rostro', 'Rostro por rostro, con fotos de ejemplo arriba', 'Recorre cinco tipos de rostro (redondo, ovalado, cuadrado, corazón y alargado) con tres cortes recomendados para cada uno y las fotos en la parte de arriba.', 'Recorre cinco tipos de rostro y para cada uno muestra tres cortes que favorecen, con un dibujo del rostro y las fotos arriba mientras tú lo explicas abajo.', 'Contenido de guardado puro: lista clara más imágenes. La clienta se reconoce en su rostro y te pide cita para ese corte.', 'Tú a cámara en la mitad de abajo y arriba un collage con el rostro y tres fotos. Un rostro cada 5–6 s y la lista completa en el caption.', '/reels/cover-nov-DbllXgWMHXx.jpg', 'https://www.instagram.com/p/DbllXgWMHXx/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DbllXgWMHXx%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Flequillos 2026: cuál te favorece', 'Tipos de flequillo según la forma del rostro', 'La estilista explica qué flequillo equilibra cada tipo de rostro, con fotos de ejemplo alrededor y el título «Bangs 2026».', 'Explica tres tipos de flequillo y a qué rostro favorece cada uno, con fotos de ejemplo alrededor y un título con el año para que parezca actual.', 'El flequillo es la duda número uno antes de un cambio. Poner el año en el título dispara el clic de «esto es lo nuevo».', 'Tú a cámara con pantalla verde o recortes de fotos alrededor. Título grande arriba («Flequillos 2026») y un consejo por rostro. Cierra: «¿cuál sería el tuyo?».', '/reels/cover-nov-DbHETRNTnOG.jpg', 'https://www.instagram.com/p/DbHETRNTnOG/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DbHETRNTnOG%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'El mejor corte no es el que está de moda', 'Rostro redondo: los cortes que lo armonizan', 'A cámara, con un dibujo del rostro y tres fotos arriba: qué cortes armonizan un rostro redondo (capas largas, liso largo, wolf cut).', 'Empieza con «El mejor corte no es el que está de moda, es el que armoniza con tu rostro» y explica un tipo de rostro con tres cortes de ejemplo.', 'Contradice una creencia (seguir la moda) y da una respuesta útil. La pregunta final genera comentarios de gente diciendo su tipo de rostro.', 'Tú a cámara en la mitad de abajo y el collage del rostro arriba. Un rostro por reel: así tienes una serie de cinco. Caption: «¿Ya sabes cuál es el ideal para ti?».', '/reels/cover-nov-DZLqSvPv0VK.jpg', 'https://www.instagram.com/p/DZLqSvPv0VK/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DZLqSvPv0VK%');

insert into public.reel_inspirations (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'El corte de tus sueños depende de tus facciones', 'Por qué el look de Pinterest no te queda igual', 'La estilista explica, con un antes y después del corte largo a capas detrás, por qué un look de Pinterest no queda igual en todas: hay que adaptarlo a las facciones.', 'Habla de la frustración de llevar una foto de Pinterest y no verte igual, y explica cómo adaptas el corte a la forma del rostro.', 'Toca un dolor real y muy compartido («me lo hice y no me veo») y te posiciona como la que sabe adaptar, no copiar.', 'Tú a cámara en el salón con la foto del corte detrás (pantalla verde). Gancho: «El corte de tus sueños no depende de las modas». Cierra con «escríbeme y lo adaptamos a ti».', '/reels/cover-nov-DZ5b_5aCUTp.jpg', 'https://www.instagram.com/p/DZ5b_5aCUTp/', 'active'
where not exists (select 1 from public.reel_inspirations where instagram_url like '%DZ5b_5aCUTp%');

insert into public.reel_transitions (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Sí a ese cambio', 'Transición al resultado con el mensaje «sí a atreverte»', 'El resultado de color (castaño con ondas) presentado con el mensaje «sí a ese cambio que llevas tiempo pensando». Vende la emoción de atreverse.', 'Transición del antes al después con el texto «Sí a ese cambio que llevas tiempo pensando» y un caption que hable de cómo se siente la clienta.', 'Vende la emoción de atreverse, no la técnica. A quien lleva meses pensando en cambiar le da el empujón para reservar.', 'Antes y después con el mismo encuadre y la misma luz. Corta en el golpe de la música. Texto corto arriba y la historia en el caption.', '/reels/cover-nov-DeHlxBnOhr7.jpg', 'https://www.instagram.com/p/DeHlxBnOhr7/', 'active'
where not exists (select 1 from public.reel_transitions where instagram_url like '%DeHlxBnOhr7%');

insert into public.reel_transitions (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Rubio sol: de morena a rubia', 'Cambio radical de color y corte en una transición', 'De morena natural a «Rubio Sol» con un corte más corto y dinámico. El caption cuenta el proceso y por qué ese tono ilumina el rostro.', 'Transición de un cambio radical (de morena a rubia y corte más corto) con un nombre propio para el tono, como «Rubio Sol».', 'Los cambios radicales son lo más visto del sector. Ponerle nombre al tono lo convierte en un servicio que la gente pide.', 'Plano frontal antes y después en el mismo sitio. La clienta mira a cámara al final. En el caption, el nombre del tono y una frase del proceso.', '/reels/cover-nov-DR0MgxxD0hD.jpg', 'https://www.instagram.com/p/DR0MgxxD0hD/', 'active'
where not exists (select 1 from public.reel_transitions where instagram_url like '%DR0MgxxD0hD%');

insert into public.reel_transitions (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Tendencias de esta temporada', 'Secuencia de looks: bob, butterfly, flequillos y castaños naturales', 'Secuencia rápida de fotos editoriales con las tendencias de la temporada según la estilista: bob, butterfly, flequillos y castaños naturales.', 'Una secuencia de seis a ocho fotos de looks que vas a ver esta temporada, con el texto fijo «Lo que vas a pedir esta temporada».', 'Las tendencias se guardan y se comparten. Sin hablar, el ritmo de las fotos mantiene la atención hasta el final.', 'Elige seis a ocho fotos del mismo estilo (mismo encuadre de rostro). Cambia cada 0,5–1 s al ritmo de la música y deja el texto fijo arriba.', '/reels/cover-nov-DWPYK0qsdu4.jpg', 'https://www.instagram.com/p/DWPYK0qsdu4/', 'active'
where not exists (select 1 from public.reel_transitions where instagram_url like '%DWPYK0qsdu4%');

insert into public.reel_transitions (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'Cortes que integran las canas', 'Secuencia de cortes que hacen que las canas se vean bonitas', 'Fotos de cortes con capas y textura que integran las canas. El mensaje: no se trata de taparlas, sino de encontrar el corte adecuado.', 'Una secuencia de cortes que favorecen a quien lleva canas, con el texto «No se trata de taparlas».', 'Cambia el enfoque de un tema delicado (taparlas por lucirlas) y habla a un público que crece y busca referencias.', 'Seis fotos de cortes con canas o tonos fríos, al mismo tamaño. Cambio rápido al ritmo y texto fijo. En el caption explica por qué las capas ayudan.', '/reels/cover-nov-DZVYzUuMe7X.jpg', 'https://www.instagram.com/p/DZVYzUuMe7X/', 'active'
where not exists (select 1 from public.reel_transitions where instagram_url like '%DZVYzUuMe7X%');

insert into public.reel_transitions (title, short_description, description, idea_text, why_text, how_text, cover_image, instagram_url, status)
select 'El flequillo que te favorece', 'Secuencia de flequillos para elegir el tuyo', 'Fotos de distintos flequillos (cortina, recto, desfilado) con el mensaje de que el flequillo correcto puede cambiar cómo se ve un rostro.', 'Una secuencia de flequillos distintos con el texto «¿Cuál sería el tuyo?» para que la gente comente su favorito.', 'Pregunta fácil de responder (un número o un nombre) que dispara comentarios, y cada comentario es una posible cita.', 'Seis fotos de flequillos con el mismo encuadre. Numéralas en pantalla (1, 2, 3…) para que comenten el número. Cambio cada 1 s.', '/reels/cover-nov-DZsj9NnsiPj.jpg', 'https://www.instagram.com/p/DZsj9NnsiPj/', 'active'
where not exists (select 1 from public.reel_transitions where instagram_url like '%DZsj9NnsiPj%');
